import requests
from pathlib import Path
import zipfile
# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    if not url or not filename:
        return ("Error: URL and filename must be non-empty strings.", [])

    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)
        zip_path = DOWNLOAD_DIR / filename

        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()

        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        if not zipfile.is_zipfile(zip_path):
            return ("Error: Downloaded file is not a valid zip archive.", [])

        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)

        file_list = [str(f.relative_to(ZIP_DIR)) for f in ZIP_DIR.iterdir() if f.is_file()]
        return ("Success", file_list)

    except (requests.RequestException, OSError, zipfile.BadZipFile) as e:
        return (f"Error: {str(e)}", [])

