import requests
import pandas as pd
import matplotlib.pyplot as plt
def task_func(api_url):
    if not isinstance(api_url, str):
        raise TypeError("api_url must be a string.")
    response = requests.get(api_url)
    if response.status_code != 200:
        raise requests.HTTPError(f"API request failed with status {response.status_code}")
    data = response.json()
    if isinstance(data, list):
        df = pd.DataFrame(data)
    else:
        df = pd.DataFrame([data])
    if df.empty:
        return df, None
    numeric_cols = df.select_dtypes(include='number').columns
    if len(numeric_cols) == 0:
        return df, None
    fig, ax = plt.subplots()
    df[numeric_cols].plot(ax=ax)
    return df, ax

import requests
import pandas as pd
def task_func(api_url):
    if not isinstance(api_url, str):
        raise TypeError("api_url must be a string.")
    response = requests.get(api_url)
    if not response.ok:
        raise requests.exceptions.HTTPError(f"API request failed with status {response.status_code}")
    data = response.json()
    df = pd.DataFrame(data)
    if df.empty:
        return df, None
    import matplotlib.pyplot as plt
    fig, ax = plt.subplots()
    if len(df.columns) >= 2:
        numeric_cols = df.select_dtypes(include='number').columns
        if len(numeric_cols) >= 2:
            x = df[numeric_cols[0]]
            y = df[numeric_cols[1]]
            ax.plot(x, y)
        else:
            ax.plot(df[df.columns[0]])
    else:
        ax.plot(df[df.columns[0]])
    return df, ax

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("webpage_url must be a non-empty string.")
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Failed to fetch URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')
        if not table:
            return 0
        table = table[0]
        headers = [th.text_content().strip() for th in table.xpath('.//th')]
        rows = []
        for tr in table.xpath('.//tr'):
            cols = [td.text_content().strip() for td in tr.xpath('.//td')]
            if cols:
                rows.append(cols)
        if not rows:
            return 0
        if headers:
            df = pd.DataFrame(rows, columns=headers)
        else:
            df = pd.DataFrame(rows)
