import collections
import json
import requests

def task_func(user, API_URL = 'https://api.github.com/users/'):
    if not user or not isinstance(user, str):
        raise ValueError("User must be a non-empty string.")

    url = f"{API_URL}{user}/repos"

    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to fetch repositories for user '{user}': {e}")

    try:
        repos = response.json()
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON response from GitHub API: {e}")

    if not isinstance(repos, list):
        raise ValueError("Unexpected response format from GitHub API.")

    repo_data = []
    for repo in repos:
        name = repo.get('name')
        created_at = repo.get('created_at')
        if name and created_at:
            repo_data.append((name, created_at))

    repo_data.sort(key=lambda x: x[1])

    return [name for name, _ in repo_data]

