from flask import Flask
from flask_restful import Resource, Api
import requests

def task_func(api_url, template_folder):
    if not api_url or not isinstance(api_url, str):
        raise ValueError("api_url must be a non-empty string.")
    if not template_folder or not isinstance(template_folder, str):
        raise ValueError("template_folder must be a non-empty string.")

    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalData(Resource):
        def get(self):
            try:
                response = requests.get(api_url, timeout=10)
                response.raise_for_status()
                return response.json(), 200
            except requests.ConnectionError:
                return {"error": "Failed to connect to external API"}, 503
            except requests.HTTPError as e:
                return {"error": f"HTTP error: {str(e)}"}, response.status_code
            except Exception as e:
                return {"error": f"Unexpected error: {str(e)}"}, 500

    api.add_resource(ExternalData, '/')

    return app

import requests
import json
from bs4 import BeautifulSoup
def task_func(url: str, file_name: str = "Output.txt") -> str:
    if not url:
        raise ValueError("URL must be a non-empty string.")
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to retrieve the webpage: {e}")
    try:
        soup = BeautifulSoup(response.text, 'html.parser')
        title = soup.title.string.strip() if soup.title and soup.title.string else None
    except Exception as e:
        raise ValueError(f"Error parsing the webpage content: {e}")
    with open(file_name, 'a') as f:
        f.write(json.dumps({"title": title}) + '\n')
    return file_name
